mapper.select:
SELECT a.id, a.device_id, a.device_name, a.device_ip, a.alarm_type, a.alarm_level, a.alarm_status, a.alarm_time, a.confirm_user_id, a.confirm_user_name, a.confirm_time, a.handle_remark, a.recover_time, a.close_time, a.duration_minutes, a.notify_sent, a.remark, a.create_time, a.update_time, t.type_name AS deviceTypeName FROM alarm_record a LEFT JOIN device d ON a.device_id = d.id LEFT JOIN device_type t ON d.device_type_id = t.id
AND (a.device_name LIKE CONCAT('%', #{q.keyword}, '%') OR a.device_ip LIKE CONCAT('%', #{q.keyword}, '%'))
AND a.alarm_level = #{q.level}
AND a.alarm_status = #{q.status}
AND a.alarm_type = #{q.type}
AND a.alarm_time >= CONCAT(#{q.startDate}, ' 00:00:00')
AND a.alarm_time <= CONCAT(#{q.endDate}, ' 23:59:59')
ORDER BY a.alarm_time DESC, a.id DESC

SELECT a.alarm_level AS name, COUNT(1) AS value
FROM alarm_record a

    a.alarm_type = 'OFFLINE'

        AND a.alarm_time >= #{start}


        AND a.alarm_time < #{end}


GROUP BY a.alarm_level

SELECT a.alarm_type AS name, COUNT(1) AS value
FROM alarm_record a


        a.alarm_time >= #{start}


        AND a.alarm_time < #{end}


GROUP BY a.alarm_type
